workspace "Parcel Tracker" "C4 model of the parcel delivery tracking platform" {

    !identifiers hierarchical

    model {
        customer = person "Customer" "Looks up the status of their parcels"

        parcelTracker = softwareSystem "Parcel Tracker" "Platform for tracking parcel deliveries, owned and operated by our company" {
            webPortal = container "Web Portal" "Where customers look up shipments" "Web application" {
                pricingRules = component "Pricing Rules Library" "Computes delivery prices from weight and zone" "Library"
            }
            dispatchService = container "Dispatch Service" "Assigns parcels to couriers" "Service" {
                pricingRules = component "Pricing Rules Library" "Computes delivery prices from weight and zone" "Library"
            }
            database = container "Database" "Stores shipments and dispatch records" "Database" "Database"
        }

        emailProvider = softwareSystem "Email Delivery Provider" "Sends customer notification emails, operated by a different organization" "External"

        customer -> parcelTracker "looks up the status of their parcels"
        parcelTracker.webPortal -> parcelTracker.database "reads shipments from"
        parcelTracker.dispatchService -> parcelTracker.database "writes dispatch records to"
        parcelTracker.dispatchService -> emailProvider "sends customer notification emails through"
    }

    views {
        systemContext parcelTracker "SystemContext" {
            include *
            autoLayout
            title "System Context for Parcel Tracker"
        }

        container parcelTracker "Containers" {
            include *
            autoLayout
            title "Containers for Parcel Tracker"
        }

        component parcelTracker.webPortal "WebPortalComponents" {
            include *
            autoLayout
            title "Components of Web Portal"
        }

        component parcelTracker.dispatchService "DispatchServiceComponents" {
            include *
            autoLayout
            title "Components of Dispatch Service"
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Component" {
                background #85BBF0
                color #000000
            }
            element "Database" {
                shape Cylinder
            }
        }
    }
}

